<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';

$cari=trim((string)($_GET['cari']??''));
$status=(string)($_GET['status']??'aktif');
if(!in_array($status,['aktif','nonaktif','semua'],true))$status='aktif';
$allowedPerPage=[5,10,20,50,100];
$per_page=(int)($_GET['per_page']??20);
if(!in_array($per_page,$allowedPerPage,true))$per_page=20;
$page=max(1,(int)($_GET['page']??1));
$where=[];$params=[];
if($status!=='semua'){$where[]='g.status = ?';$params[]=$status;}
if($cari!==''){$where[]='(g.nip LIKE ? OR g.nama LIKE ? OR g.mapel LIKE ? OR g.kode_qr LIKE ?)';$q='%'.$cari.'%';array_push($params,$q,$q,$q,$q);}
$where_sql=$where?'WHERE '.implode(' AND ',$where):'';
$st=$pdo->prepare("SELECT COUNT(*) FROM guru g $where_sql");$st->execute($params);$total=(int)$st->fetchColumn();
$pages=max(1,(int)ceil($total/$per_page));if($page>$pages)$page=$pages;$offset=($page-1)*$per_page;
$st=$pdo->prepare("SELECT g.* FROM guru g $where_sql ORDER BY g.nama ASC LIMIT $per_page OFFSET $offset");$st->execute($params);$rows=$st->fetchAll();
$sum=$pdo->query("SELECT COUNT(*) semua, SUM(status='aktif') aktif, SUM(status='nonaktif') nonaktif FROM guru")->fetch();
function guru_page_url(int $p):string{$q=$_GET;$q['page']=$p;return '?'.http_build_query($q);}
$page_title='Data Guru';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
